rows=[('rybak-za-monety','rybak_za_monety/4-1-0-195','01.06.2012','70 уровень, покупка 2 500 000 монет, продажа 250 000 монет; мозги и время в таблице не указаны.',fish,fdig),('rybak-za-zombaksy','rybak_za_zombaksy/4-1-0-194','01.06.2012','35 уровень, покупка 150 зомбаксов, продажа 250 000 монет, 5 опыта, 1 мозг, 90 минут. Подписи изображения ошибочно называют его рыбаком с мозгами и рыбаком за монеты.',fish,fdig),('torgovets-za-monety','torgovec_za_monety/4-1-0-190','01.06.2012','60 уровень, покупка 1 000 000 монет, продажа 100 000 монет, 1000 опыта, 1 мозг.','Обмен ограничен общим лимитом подарков; после обмена приносит коробку.','Копать под торговцем, по статье, нельзя.'),('torgovets-za-zombaksy','torgovec_za_zombaksy/4-1-0-182','01.06.2012','10 уровень, покупка 100 зомбаксов, продажа 10 000 монет, 1000 опыта, 1 мозг.','Обмен ограничен общим лимитом подарков; после обмена приносит коробку.','Копать под торговцем, по статье, нельзя.'),('kladoiskatel','kladoiskatel_za_monety/4-1-0-185','01.06.2012','Вариант за монеты: 15 уровень, 300 000 монет, продажа 30 000 монет, 500 опыта, 1 мозг, 90 минут.',treasure,tdig),('kladoiskatel','kladoiskatel_za_zombaksy/4-1-0-186','01.06.2012','Вариант за зомбаксы: 15 уровень, 30 зомбаксов, продажа 30 000 монет, 500 опыта, 1 мозг, 90 минут.',treasure,tdig),('zvezdochet-za-monety','zvezdochet/4-1-0-605','26.07.2014','56 уровень, покупка 3 500 000 монет, продажа 350 000 монет, 50 опыта, 1 мозг, 90 минут.','Опыт, монеты, Лучи добра; коллекции Байкерская, Знаков, Туристическая, Школьная, Президентская, Зимняя, Райская, Вкусная, Секретная, Гипер, Адская, Майя, Любовная, Тинейджерская, Компа, Временная. Приносит добычу в мешках.','В статье сведения о копании под ним отсутствуют.')]
for slug,path,date,params,work,dig in rows:
 x=by[slug];url='https://zf.3dn.ru/publ/zombi/'+path;rid='zf3dn-worker-'+path.rsplit('/',1)[-1]
 if not any(s['url']==url for s in x['sources']):x['sources'].append({'url':url,'label':'ZF.3dn: историческая карточка работника'})
 rec={'original_id':rid,'original_category':'Зомби и работники','version':'историческая браузерная игра, платформа не уточнена','date':date+' — дата публикации; дата редакции неизвестна','fields':{'Параметры':params,'Действия и указанная добыча':work,'Копание у друзей':dig},'confidence':'Фанатский источник, вероятности отсутствуют; дата публикации не гарантирует дату всех данных. Независимость от zombi-ferma.ru не установлена.'};x.setdefault('prior_records',[]);x['prior_records']=[r for r in x['prior_records'] if r.get('original_id')!=rid]+[rec]
p.write_text(json.dumps(a,ensure_ascii=False,indent=2));print('imported',len(rows),'records in',len(set(r[0] for r in rows)),'cards')
